/* Exact browser inference from a trained sklearn model, plus historical context. */
(() => {
 'use strict';
 const data=window.BIKE_DATA,model=window.BIKE_MODEL,results=window.MODEL_RESULTS,$=id=>document.getElementById(id);
 if(!data?.rows?.length||!model||!results||!globalThis.BikeModelRuntime){$('loadError').hidden=false;return;}
 const names=['Воскресенье','Понедельник','Вторник','Среда','Четверг','Пятница','Суббота'],fmt=n=>new Intl.NumberFormat('ru-RU').format(n),dec=n=>n.toLocaleString('ru-RU',{maximumFractionDigits:1});
 const exact=new Map(),fallback=new Map();
 for(const [d,h,w,n,s] of data.rows){exact.set(`${d}-${h}-${w}`,{n,s});const k=`${d}-${h}`,g=fallback.get(k)||{n:0,s:0};g.n+=n;g.s+=s;fallback.set(k,g);}
 $('totalRows').textContent=fmt(data.rows.reduce((a,r)=>a+r[3],0));$('meanDemand').textContent=fmt(Math.round(data.rows.reduce((a,r)=>a+r[4],0)/data.rows.reduce((a,r)=>a+r[3],0)));
 $('testMae').textContent=dec(results.test.selected.mae);$('improvementNote').textContent=`MAE ниже базового на ${dec(results.test.mae_improvement_percent)}%`;
 let current=[],day=5,weather=1,hour=17;
 const calendar=()=>({month:Number($('month').value),year:Number($('year').value),holiday:Number($('holiday').checked)});
 function historical(h){const match=exact.get(`${day}-${h}-${weather}`),backup=fallback.get(`${day}-${h}`),g=match&&match.n>=5?match:backup;return {hour:h,mean:g?g.s/g.n:null,n:g?.n||0,matched:match?.n||0,fallback:!(match&&match.n>=5)};}
 function predict(h){const c=calendar();return BikeModelRuntime.predict(model,[h,day,c.month,weather,c.holiday,Number(day!==0&&day!==6&&!c.holiday),c.year]);}
 function chooseHour(h){hour=h;$('hour').value=h;$('hourLabel').textContent=`${String(h).padStart(2,'0')}:00`;const r=current[h];$('estimate').textContent=fmt(Math.round(r.prediction));$('historicalEstimate').textContent=`${fmt(Math.round(r.mean||0))} аренд / час`;$('modelNote').textContent='HistGradientBoosting · календарь и категория погоды';
 $('sampleNote').textContent=r.fallback?`Для исторического среднего мало совпадений по погоде (${r.matched}). Использованы ${r.n} наблюдений без учёта погоды. Это не размер выборки ML-модели.`:`Историческое среднее: ${r.n} наблюдений для дня недели, часа и погоды; месяцы и годы объединены. ML учитывает календарь отдельно.`;
 const warnings=[],c=calendar();if(weather===4)warnings.push('В обучении лишь 3 записи с тяжёлой погодой: ML-прогноз ненадёжен.');if(c.year===1&&c.month>=6)warnings.push('Для этого месяца 2012 года в train нет данных: модель переносит закономерности других периодов.');$('scenarioWarning').hidden=!warnings.length;$('scenarioWarning').textContent=warnings.join(' ');
 $('chartReadout').textContent=`${String(h).padStart(2,'0')}:00 · ML: ${fmt(Math.round(r.prediction))} · среднее: ${fmt(Math.round(r.mean||0))} аренд / час`;
 document.querySelectorAll('.chart-point').forEach(p=>p.setAttribute('aria-pressed',String(Number(p.dataset.hour)===h)));const marker=$('selectedMarker');if(marker){marker.setAttribute('cx',String(48+h*590/23));marker.setAttribute('cy',String(250-r.prediction/Number(marker.dataset.max)*210));}}
 function renderChart(){day=Number($('weekday').value);weather=Number($('weather').value);hour=Number($('hour').value);current=Array.from({length:24},(_,h)=>({...historical(h),prediction:predict(h)}));const max=Math.ceil(Math.max(1,...current.flatMap(r=>[r.mean||0,r.prediction]))/100)*100,x=h=>48+h*590/23,y=v=>250-v/max*210,points=current.map(r=>`${x(r.hour)},${y(r.prediction)}`).join(' '),past=current.map(r=>`${x(r.hour)},${y(r.mean||0)}`).join(' ');
 let svg=`<svg viewBox="0 0 665 300" role="group" aria-label="ML-прогноз и историческое среднее по часам, ${names[day]}. Точки доступны с клавиатуры."><defs><linearGradient id="chartFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#b7d7ac" stop-opacity=".45"/><stop offset="100%" stop-color="#dcebd5" stop-opacity=".05"/></linearGradient></defs>`;
 for(let i=0;i<=4;i++){const v=max*i/4;svg+=`<line x1="48" y1="${y(v)}" x2="638" y2="${y(v)}" stroke="#e9eee4" ${i?'stroke-dasharray="3 5"':''}/><text x="34" y="${y(v)+3}" text-anchor="end" font-size="10" fill="#748069">${v}</text>`;}
 for(const h of [0,4,8,12,16,20,23])svg+=`<text x="${x(h)}" y="275" text-anchor="middle" font-size="10" fill="#748069">${String(h).padStart(2,'0')}:00</text>`;
 svg+=`<polygon points="48,250 ${points} 638,250" fill="url(#chartFill)"/><polyline points="${past}" fill="none" stroke="#b58d5e" stroke-width="2" stroke-dasharray="6 5"/><polyline points="${points}" fill="none" stroke="#31745b" stroke-width="3" stroke-linejoin="round"/><circle id="selectedMarker" data-max="${max}" cx="${x(hour)}" cy="${y(current[hour].prediction)}" r="6" fill="#d4f77c" stroke="#245b43" stroke-width="3"/>`;
 for(const r of current)svg+=`<circle class="chart-point" data-hour="${r.hour}" role="button" tabindex="0" aria-pressed="${r.hour===hour}" aria-label="${r.hour}:00, ML ${Math.round(r.prediction)}, среднее ${Math.round(r.mean||0)} аренд в час" cx="${x(r.hour)}" cy="${y(r.prediction)}" r="10"><title>${r.hour}:00 · ML ${Math.round(r.prediction)} · среднее ${Math.round(r.mean||0)}</title></circle>`;
 $('chart').innerHTML=svg+'</svg>';document.querySelectorAll('.chart-point').forEach(p=>{p.addEventListener('click',()=>chooseHour(Number(p.dataset.hour)));p.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();chooseHour(Number(p.dataset.hour));}});});$('chartLabel').textContent=`${names[day]} · ${$('month').selectedOptions[0].text} ${2011+calendar().year}`;chooseHour(hour);}
 function download(content,type,name){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 $('hour').addEventListener('input',()=>chooseHour(Number($('hour').value)));$('scenarioForm').addEventListener('submit',e=>{e.preventDefault();renderChart();});for(const id of ['weekday','weather','month','year','holiday'])$(id).addEventListener('change',renderChart);
 $('export').addEventListener('click',()=>{const c=calendar();download('\uFEFFyear,month,weekday,holiday,weather,hour,ml_prediction,historical_mean,historical_observations,weather_filter_used\r\n'+current.map(r=>[2011+c.year,c.month,day,c.holiday,weather,r.hour,r.prediction.toFixed(3),r.mean?.toFixed(3)??'',r.n,!r.fallback].join(',')).join('\r\n'),'text/csv;charset=utf-8',`bike-demand-${2011+c.year}-${c.month}-day${day}.csv`);});
 function quality(){$('qualityMae').textContent=dec(results.test.selected.mae);$('baselineMae').textContent=dec(results.test.baseline.mae);$('qualityImprovement').textContent=dec(results.test.mae_improvement_percent)+'%';for(const row of results.validation){const tr=document.createElement('tr');for(const value of [row.name,dec(row.mae),dec(row.rmse),row.name===results.selected?'Выбрана':'—']){const td=document.createElement('td');td.textContent=value;tr.appendChild(td);}if(row.name===results.selected)tr.className='winning-row';$('validationRows').appendChild(tr);}
 $('testSummary').textContent=`Период: 13.09.2012 — 31.12.2012, 2 600 наблюдаемых часов. Модель: ${results.selected}. MAE: ${dec(results.test.selected.mae)}, RMSE: ${dec(results.test.selected.rmse)} аренд/час. Обучена только на train; после выбора по валидации повторное обучение не проводилось.`;
 const samples=results.test.examples,max=Math.ceil(Math.max(...samples.flatMap(r=>[r.actual,r.prediction]))/100)*100,x=i=>45+i*680/(samples.length-1),y=v=>225-v/max*190;let svg='<svg viewBox="0 0 755 270" role="img" aria-label="Факт и прогноз для 72 разнесённых во времени тестовых наблюдений">';for(let i=0;i<=4;i++){const v=max*i/4;svg+=`<line x1="45" y1="${y(v)}" x2="725" y2="${y(v)}" stroke="#e7ece2"/><text x="34" y="${y(v)+3}" text-anchor="end" font-size="10" fill="#748069">${v}</text>`;}samples.forEach((r,i)=>{svg+=`<line x1="${x(i)}" y1="${y(r.actual)}" x2="${x(i)}" y2="${y(r.prediction)}" stroke="#dce2d6"/><circle cx="${x(i)}" cy="${y(r.actual)}" r="3" fill="#bd9467"><title>${r.timestamp} · факт ${r.actual}</title></circle><circle cx="${x(i)}" cy="${y(r.prediction)}" r="3" fill="#31745b"><title>${r.timestamp} · прогноз ${Math.round(r.prediction)}</title></circle>`;});svg+='<text x="45" y="253" font-size="10" fill="#748069">Сентябрь 2012</text><text x="725" y="253" text-anchor="end" font-size="10" fill="#748069">Декабрь 2012</text></svg>';$('testChart').innerHTML=svg;}
 $('downloadMetrics').addEventListener('click',()=>download(JSON.stringify(results,null,2),'application/json','bike-demand-model-results.json'));
 function navigate(){const key=location.hash.slice(1),name=['overview','quality','data','method'].includes(key)?key:'overview';document.querySelectorAll('.page').forEach(p=>p.hidden=p.id!==name);document.querySelectorAll('[data-nav]').forEach(a=>{a.classList.toggle('active',a.dataset.nav===name);if(a.dataset.nav===name)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});$('breadcrumb').textContent={overview:'Обзор',quality:'Качество',data:'Данные',method:'О проекте'}[name];window.scrollTo(0,0);}
 window.addEventListener('hashchange',navigate);quality();navigate();renderChart();
})();
